export interface JSONAPIError {
  id?: string;
  links?: {
    about?: string;
  };
  status?: string;
  code?: string;
  title?: string;
  detail?: string;
  source?: {
    pointer?: string;
    parameter?: string;
  };
  meta?: Record<string, any>;
}

export interface JSONAPIErrorResponse {
  errors: JSONAPIError[];
}

/**
 * Checks if a given object conforms to JSONAPIErrorResponse
 * @param obj - The object to check
 */
export function isJSONAPIErrorResponse(obj: any): obj is JSONAPIErrorResponse {
  return (
    obj &&
    Array.isArray(obj.errors) &&
    obj.errors.every((error: any) => typeof error === 'object')
  );
}

/**
 * Extracts all error details into a flat array of strings
 * @param errorResponse - The JSONAPIErrorResponse object
 */
export function extractErrorDetails(
  errorResponse: JSONAPIErrorResponse,
): [string, string][] {
  return errorResponse.errors.map((error: JSONAPIError) => {
    const fieldName = getLastSegment(error?.source?.pointer ?? '');

    return [fieldName, error.detail || error.title || 'Unknown error'];
  });
}

/**
 * Finds errors related to a specific field using the source.pointer
 * @param errorResponse - The JSONAPIErrorResponse object
 * @param field - The field name to filter errors by
 */
export function findErrorsByField(
  errorResponse: JSONAPIErrorResponse,
  field: string,
): JSONAPIError[] {
  return errorResponse.errors.filter(
    (error: JSONAPIError) =>
      error.source?.pointer === `/${field}` ||
      error.source?.parameter === field,
  );
}

/**
 * Extracts the last segment of a path by splitting on '/'.
 *
 * @param path - The path string from which to extract the last segment.
 * @returns The last segment of the path. Returns an empty string if the path is empty.
 */
function getLastSegment(path: string): string {
  // Split the path by '/' and filter out empty segments (to handle trailing slashes)
  const segments = path.split('/').filter((segment) => segment.length > 0);

  // Return the last segment or an empty string if no segments exist
  return segments.length > 0 ? segments[segments.length - 1] : '';
}
