export class UnderwritingIncompleteError extends Error {
  detail?: string;

  constructor(errorData?: any) {
    super('underwriting-incomplete');

    if (errorData?.errors && Array.isArray(errorData.errors)) {
      const underwritingError = errorData.errors.find(
        (error: any) => error.code === 'underwriting-incomplete',
      );

      if (underwritingError) {
        this.detail = underwritingError.detail;
      }
    }
  }
}

