export class ScopedError extends Error {
  detail: string;
  policy: string | null;
  constructor(frontEndError: string, detail: string) {
    super(frontEndError);
    this.detail = detail;
    this.policy = getPolicy();
  }
}

export function getPolicy(): string | null {
  const queryParams = new URLSearchParams(window.location.search);

  // Partner/Program paths
  if (queryParams.has('session')) {
    return queryParams.get('session');
  }

  // Reflow Path
  if (queryParams.has('token')) {
    const token = queryParams.get('token');
    if (token === null) {
      return '';
    }
    const decodedJwt = jwtDecode(token);
    if (typeof decodedJwt !== 'object' || decodedJwt === null) {
      return '';
    }
    const session: AffinitySession = validateAffinitySession(decodedJwt);

    return session.insurance_policy_uuid;
  }

  return '';
}

export class ExpiredJwtError extends ScopedError {
  constructor() {
    super('expired-jwt', 'JWT token has expired');
  }
}

export function isJwtExpired(jwt: string | undefined): boolean {
  if (!jwt) {
    return false;
  }

  try {
    // JWT format: header.payload.signature
    // Split the JWT to get the header part
    const parts = jwt.split('.');
    if (parts.length !== 3) {
      return false;
    }

    // Decode the header (first part) which contains exp
    const headerBase64 = parts[0];
    const headerJson = atob(headerBase64.replace(/-/g, '+').replace(/_/g, '/'));
    const header = JSON.parse(headerJson) as {exp?: number};

    if (!header || typeof header.exp !== 'number') {
      return false;
    }

    // JWT exp is in seconds, Date.now() is in milliseconds
    const currentTimeInSeconds = Math.floor(Date.now() / 1000);
    return header.exp < currentTimeInSeconds;
  } catch (error) {
    // If we can't decode the JWT, return false and let other error handlers deal with it
    return false;
  }
}

