import {Static, Record, String} from 'runtypes';

import {PackageSchema} from './package';

// see: https://github.com/crucible-risk/webserver/blob/adb1723/www/serializers/account.py#L66
export const AccountPackageSchema = PackageSchema.pick(
  'aggregate_limit',
  'coalition_policy_number',
  'created_at',
  'currency_code',
  'default_retention',
  'effective_date',
  'end_date',
  'insurance_market',
  'lifecycle_state',
  'premium',
  'uuid',
  'w2r_association',
  'w2r_association_id',
).And(
  Record({
    broker_uuid: String,
  }),
);

export type AccountPackage = Static<typeof AccountPackageSchema>;
