import * as React from 'react';
import {useFela} from 'react-fela';
import {parse} from 'date-fns';
import DayPickerInput from 'react-day-picker/DayPickerInput';
import {SearchIndex} from 'algoliasearch';

import {TextInput, TextInputAttributes} from '@crucible-risk/text-input';
import {Select, Option} from '@crucible-risk/select';
import {ComboBox, Option as ComboBoxOption} from '@crucible-risk/combo-box';
import {Spacing} from '@crucible-risk/spacing';
import {Spinner} from '@crucible-risk/spinner';
import {Typography} from '@crucible-risk/typography';
import {Checkbox} from '../Checkbox/Checkbox';

import {stateOptions, employeeOptions} from '/utils/options';
import {formatDate, formatCurrency} from '/utils/intl';

import type {FieldBlockType} from '/lib/content';
import {
  AddressAutoCompleteService,
  AddressGeocoderService,
  PlaceSuggestion,
} from '/lib/geocoder';

import {MonetaryInput} from '/components/MonetaryInput';
import {IndustrySearchField} from '/components/IndustrySearchField';

import type {
  GeneralInfoFormValues,
  GeneralInfoFormChangeHandler,
  GeneralInfoFormBlurHandler,
  GeneralInfoFormFlags,
  GeneralInfoValidationErrors,
} from '/hooks/useGeneralInfoForm';

import poweredByGoogleImage from '/images/poweredByGoogle.png';

import {
  CompanyDetailsContext,
  CompanyDetailsContextType,
} from './CompanyDetailsContext';
import {CompanyDetailsInput} from './CompanyDetailsInput';

import {
  StyleProps,
  FORM,
  INPUT_GROUP,
  INPUT_ROW,
  INPUT,
  INPUTS,
  LABEL,
  DATE_PICKER_WRAPPER,
  ROW,
} from './styles';
import {disabledDays} from './utils/disabled-days';
import {useSkuApi} from '../../hooks/useSkuApi';
import {DistributionProgramsRequest} from '@crucible-risk/sku-api-schema';
import {affinityReferrerUUID} from '/hooks/useAffinityReferrer';
export type {
  GeneralInfoFormValues,
  GeneralInfoFormChangeHandler,
  GeneralInfoFormBlurHandler,
  GeneralInfoFormFlags,
  GeneralInfoValidationErrors,
} from '/hooks/useGeneralInfoForm';

export interface IndustryOption {
  value: number;
  label: string;
}

// Little internal helper wrapper around text input for date selector
const DateInput = React.forwardRef((props: TextInputAttributes, ref: any) => {
  return <TextInput {...props} size="small" ref={ref} readOnly />;
});

const PhoneToolTipInfo =
  'In the event of a security incident, your number gives us a\n' +
  '                      way to contact you directly.';

const BusinessNameToolTipInfo =
  'If a sole proprietor, please list ' +
  'your full legal name or DBA under the first and last name';

const WebsiteDomianToolTipInfo =
  'Please leave the Website Domain ' +
  'section blank if you do not have a registered website';

export type CompanyDetailsProps = {
  algolia: SearchIndex;
  industryName: string;
  labelStyle: 'stacked' | 'inline';
  values: GeneralInfoFormValues;
  dirty: GeneralInfoFormFlags;
  validationErrors: GeneralInfoValidationErrors;
  valid: GeneralInfoFormFlags;
  editing?: boolean;
  content: Record<string, FieldBlockType>;
  onChange: GeneralInfoFormChangeHandler;
  onBlur: GeneralInfoFormBlurHandler;
  hideFields?: Array<keyof GeneralInfoFormValues>;
  geocoder: {
    addressAutocompleteService: AddressAutoCompleteService;
    addressGeocoderService: AddressGeocoderService;
  };
  setErrorState: (error: Error) => void;
  showPrograms: boolean;
  agencyProgramFlag: boolean;
};

export const CompanyDetails = ({
  algolia,
  industryName,
  labelStyle,
  values,
  valid,
  dirty,
  validationErrors,
  content,
  hideFields = [],
  editing = false,
  onChange: handleChange,
  onBlur: handleBlur,
  geocoder: {addressAutocompleteService, addressGeocoderService},
  setErrorState,
  showPrograms,
  agencyProgramFlag,
}: CompanyDetailsProps) => {
  const {css} = useFela<StyleProps>({labelStyle});
  const [addressSearch, setAddressSearch] = React.useState<{
    searching: boolean;
    places: Array<PlaceSuggestion>;
  }>({searching: false, places: []});

  const context = React.useMemo<CompanyDetailsContextType>(
    () => ({
      labelStyle,
      values,
      valid,
      dirty,
      validationErrors,
      fieldContent: content,
      handleChange,
      handleBlur,
      editing,
      hidden: hideFields,
    }),
    [
      labelStyle,
      values,
      dirty,
      validationErrors,
      valid,
      handleChange,
      handleBlur,
      content,
      editing,
      hideFields,
    ],
  );

  // state will be deprecated in future, for now we just keep both values sync
  const handleStateFieldChange = (selectedState: string) => {
    handleChange('administrative_area', selectedState);
    handleChange('state', selectedState);
  };

  const handleAddressFieldChange = React.useCallback(
    (value) => {
      setAddressSearch({...addressSearch, searching: true});
      handleChange('streetLine1', value);
      addressAutocompleteService(value.toString()).then((places) => {
        setAddressSearch({searching: false, places});
      });
    },
    [addressSearch, handleChange, addressAutocompleteService],
  );

  const handleAddressSuggestion = React.useCallback(
    (value: string) => {
      addressGeocoderService(value).then((address) => {
        handleChange('streetLine1', address.streetLine1);
        handleChange('streetLine2', address.streetLine2);
        handleChange('city', address.city);
        handleChange('administrative_area', address.state);
        handleChange('state', address.state);
        handleChange('zipcode', address.zipcode);
      });
    },
    [handleChange, addressGeocoderService],
  );

  const buildPlacesElements = React.useCallback(() => {
    const elements = [];

    addressSearch.places?.map((place) => {
      elements.push(
        <ComboBoxOption key={place.place_id} value={place.place_id}>
          {place.description}
        </ComboBoxOption>,
      );
    });

    if (elements.length) {
      elements.push(
        <img
          key="attribution"
          alt="google attribution"
          src={poweredByGoogleImage}
          className={css({marginTop: 8, float: 'right'})}
        />,
      );
    }

    return elements;
  }, [addressSearch, css]);

  const [, api] = useSkuApi({});
  const disableDistributionPrograms =
    !values.companyRevenue || !values.industry;
  const [distributionPrograms, setDistributionPrograms] = React.useState([
    {label: '', value: ''},
  ]);

  // Fetch distribution programs when company revenue, industry or effective date changes
  React.useEffect(
    () => {
      // Fetch only when company revenue and industry are set
      if (!disableDistributionPrograms && showPrograms) {
        const requestData: DistributionProgramsRequest = {
          affinity_referrer_uuid: affinityReferrerUUID,
          effective_date: values.effectiveDate
            .toISOString()
            .replace(/T.*$/, ''),
          company_revenue: values.companyRevenue,
          industry_id: values.industry,
          business_type: 'BUSINESS_TYPE_NEW',
        };
        if (values.renewalOfID) {
          requestData.business_type = 'BUSINESS_TYPE_RENEWAL';
        }
        api
          .listAvailablePrograms(requestData)
          .then((response) => {
            if (response === null && agencyProgramFlag) {
              var err = new Error('program-not-found');
              setErrorState(err);
            }
            const label = agencyProgramFlag
              ? 'Select One'
              : 'Select One, If Applicable';
            setDistributionPrograms([
              {
                value: '',
                label: label,
              },
              ...(response !== null
                ? response.map((obj) => ({
                    label: obj.tag,
                    value: obj.tag,
                  }))
                : []),
            ]);
            // If the current distribution program is not the latest program list, reset it
            if (
              (response !== null
                ? !response.some((obj: {tag: string}) =>
                    Object.values(obj).includes(values.distributionPrograms),
                  )
                : true) &&
              values.distributionPrograms !== ''
            ) {
              values.distributionPrograms = '';
              if (context.validationErrors) {
                context.validationErrors.distributionPrograms =
                  'Previous Agency Program is no longer valid. Please select new program if applicable.';
              }
            }
          })
          .catch((err) => {
            setErrorState(err);
          });
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [
      disableDistributionPrograms,
      values.companyRevenue,
      values.industry,
      values.effectiveDate,
    ],
  );

  return (
    <CompanyDetailsContext.Provider value={context}>
      <div className={css(FORM)}>
        <div className={css(INPUT_GROUP)}>
          <CompanyDetailsInput field="firstName" redacted>
            {({value, ...props}) => (
              <TextInput size="small" value={value?.toString()} {...props} />
            )}
          </CompanyDetailsInput>

          <CompanyDetailsInput field="lastName" redacted>
            {({value, ...props}) => (
              <TextInput size="small" value={value?.toString()} {...props} />
            )}
          </CompanyDetailsInput>

          <CompanyDetailsInput
            field="companyName"
            redacted
            tooltip={BusinessNameToolTipInfo}
          >
            {({value, ...props}) => (
              <TextInput size="small" value={value?.toString()} {...props} />
            )}
          </CompanyDetailsInput>
          <CompanyDetailsInput field="email" redacted>
            {({value, ...props}) => (
              <TextInput size="small" value={value?.toString()} {...props} />
            )}
          </CompanyDetailsInput>
          {values.email && (
            <CompanyDetailsInput field="confirmEmail" redacted>
              {({value, ...props}) => (
                <TextInput size="small" value={value?.toString()} {...props} />
              )}
            </CompanyDetailsInput>
          )}
          <CompanyDetailsInput
            field="streetLine1"
            redacted
            renderDisplay={() => (
              <>
                {([
                  'streetLine1',
                  'streetLine2',
                  'city',
                  'state',
                  'zipcode',
                ] as const)
                  .map((field) => values[field])
                  .filter(Boolean)
                  .join(', ')}
              </>
            )}
          >
            {({value, ...props}) => (
              <ComboBox
                {...props}
                appendEnd={
                  addressSearch.searching && (
                    <Spacing right="8">
                      <Spinner size={0} />
                    </Spacing>
                  )
                }
                onChange={handleAddressFieldChange}
                onListChange={handleAddressSuggestion}
                size="small"
                value={value?.toString()}
              >
                {buildPlacesElements()}
              </ComboBox>
            )}
          </CompanyDetailsInput>
          {editing ? (
            // Expanded address block for edit mode
            <>
              <CompanyDetailsInput field="streetLine2" redacted>
                {({value, ...props}) => (
                  <TextInput
                    size="small"
                    value={value?.toString()}
                    {...props}
                  />
                )}
              </CompanyDetailsInput>
              <CompanyDetailsInput field="city" redacted>
                {({value, ...props}) => (
                  <TextInput
                    size="small"
                    value={value?.toString()}
                    {...props}
                  />
                )}
              </CompanyDetailsInput>

              <div className={css(INPUT_ROW)} style={{marginBottom: -8}}>
                <div className={css(LABEL)} />
                <div className={css(INPUTS)}>
                  <div className={css(INPUT)} style={{flexBasis: '50%'}}>
                    <CompanyDetailsInput field="state" plain redacted>
                      {({value, ...props}) => (
                        <Select
                          fill
                          size="small"
                          value={value?.toString()}
                          {...props}
                          onChange={(e) => handleStateFieldChange(e)}
                        >
                          {stateOptions.map((option) => (
                            <Option
                              key={option.value}
                              label={option.label}
                              value={option.value}
                            />
                          ))}
                        </Select>
                      )}
                    </CompanyDetailsInput>
                  </div>
                  <div className={css(INPUT)} style={{flexBasis: '50%'}}>
                    <CompanyDetailsInput field="zipcode" plain redacted>
                      {({value, ...props}) => (
                        <TextInput
                          size="small"
                          value={value?.toString()}
                          {...props}
                        />
                      )}
                    </CompanyDetailsInput>
                  </div>
                </div>
              </div>
            </>
          ) : null}

          <CompanyDetailsInput
            field="phoneNumber"
            redacted
            tooltip={PhoneToolTipInfo}
          >
            {({value, ...props}) => (
              <TextInput size="small" value={value?.toString()} {...props} />
            )}
          </CompanyDetailsInput>
        </div>
        <div className={css(INPUT_GROUP)}>
          <CompanyDetailsInput
            field="website"
            redacted
            tooltip={WebsiteDomianToolTipInfo}
            renderDisplay={({value}) => (
              <>{(value ?? '') !== '' ? value : 'No Domain'}</>
            )}
          >
            {({value, onChange, ...props}) => (
              <TextInput
                size="small"
                value={value?.toString()}
                disabled={values.noDomains}
                onChange={(e) => {
                  onChange(e);
                  // Trigger noDomains field validation
                  handleBlur('noDomains');
                }}
                style={{
                  background: values.noDomains
                    ? 'rgba(229, 231, 235, 1)'
                    : 'rgba(255, 255, 255, 0.3)',
                  marginRight: values.noDomains ? '-10px' : '0px',
                  marginLeft: values.noDomains ? '-10px' : '0px',
                }}
                {...props}
              />
            )}
          </CompanyDetailsInput>

          <CompanyDetailsInput field="noDomains" plain>
            {({value, onChange}) => (
              // eslint-disable-next-line jsx-a11y/label-has-associated-control, jsx-a11y/label-has-for
              <label className={css(ROW)} htmlFor="noDomains">
                <Checkbox
                  id="noDomains"
                  name="noDomains"
                  checked={value as boolean}
                  disabled={values.website !== ''}
                  onChange={(checked) => {
                    onChange(checked);
                  }}
                  style={{
                    background:
                      values.website !== ''
                        ? 'rgba(229, 231, 235, 1)'
                        : 'rgba(255, 255, 255, 0.3)',
                  }}
                />
                <Spacing right="8" />
                <Typography className="body5 fg-body" fill variant="bodyXSmall">
                  This company has no domains
                </Typography>
              </label>
            )}
          </CompanyDetailsInput>
          <CompanyDetailsInput
            field="industry"
            renderDisplay={() => {
              return <>{industryName}</>;
            }}
          >
            {({value, intent, ...props}) => {
              return (
                <IndustrySearchField
                  industryName={industryName}
                  algolia={algolia}
                  value={value?.toString()}
                  isError={intent === 'danger'}
                  {...props}
                />
              );
            }}
          </CompanyDetailsInput>

          <CompanyDetailsInput
            field="companyRevenue"
            renderDisplay={({value}) => (
              <>
                {formatCurrency(value as number, {
                  fractionDigits: 0,
                  currency: 'USD',
                })}
              </>
            )}
          >
            {({value, ...props}) => (
              <MonetaryInput value={value as number} {...props} />
            )}
          </CompanyDetailsInput>

          <CompanyDetailsInput
            field="grossProfitNetRevenue"
            renderDisplay={({value}) => (
              <>
                {formatCurrency(value as number, {
                  fractionDigits: 0,
                  currency: 'USD',
                })}
              </>
            )}
          >
            {({value, ...props}) => (
              <MonetaryInput value={value as number} {...props} />
            )}
          </CompanyDetailsInput>

          <CompanyDetailsInput field="employeeCount">
            {({value, ...props}) => (
              <Select fill size="small" value={value?.toString()} {...props}>
                {employeeOptions.map((option) => (
                  <Option
                    key={option.value}
                    label={option.label}
                    value={option.value}
                  />
                ))}
              </Select>
            )}
          </CompanyDetailsInput>
          <CompanyDetailsInput
            field="effectiveDate"
            renderDisplay={({value}) => (
              <>
                {formatDate(value as Date, {
                  month: 'long',
                  day: 'numeric',
                  year: 'numeric',
                })}
              </>
            )}
          >
            {({value, ...props}) => (
              <div className={css(DATE_PICKER_WRAPPER)}>
                <DayPickerInput
                  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                  // @ts-ignore
                  // http://react-day-picker.js.org/api/DayPickerInput#style
                  // Types are incomplete here - style is a valid prop
                  style={{width: '100%'}}
                  dayPickerProps={{
                    disabledDays,
                  }}
                  value={value as Date}
                  formatDate={(date) =>
                    formatDate(date, {
                      month: 'long',
                      day: 'numeric',
                      year: 'numeric',
                    })
                  }
                  inputProps={{
                    intent: 'neutral',
                  }}
                  onDayChange={props.onChange}
                  onBlur={props.onBlur}
                  parseDate={(date) => parse(date, 'MMMM d, yyyy', new Date())}
                  component={DateInput}
                />
              </div>
            )}
          </CompanyDetailsInput>
          {showPrograms ? (
            <CompanyDetailsInput field="distributionPrograms">
              {({value, ...props}) => (
                <Select
                  fill
                  size="small"
                  value={value?.toString()}
                  disabled={disableDistributionPrograms}
                  style={{
                    background: disableDistributionPrograms
                      ? 'rgba(246, 248, 250, 1)'
                      : 'rgba(255, 255, 255, 0.3)',
                  }}
                  {...props}
                >
                  {distributionPrograms.map(
                    (option: {value: any; label: any}) => (
                      <Option
                        key={option.value}
                        label={option.label}
                        value={option.value}
                      />
                    ),
                  )}
                </Select>
              )}
            </CompanyDetailsInput>
          ) : null}
        </div>
      </div>
    </CompanyDetailsContext.Provider>
  );
};
