import {
  Record,
  String,
  Array,
  Union,
  Literal,
  Static,
  Boolean,
  Optional,
  Number,
} from 'runtypes';

const ApplicationQuestionSchema = Record({
  id: String,
  question_text: String,
  answer_text: Optional(String.Or(Number)),
  answer_options: Optional(
    Array(
      Record({
        label: String,
        value: String,
      }),
    ),
  ),
  required: Boolean,
  input_type: Optional(String),
});

export const ApplicationQuestionsSchema = Record({
  status: Union(Literal('complete'), Literal('incomplete')),
  application_questions: Array(ApplicationQuestionSchema),
});

export type ApplicationQuestions = Static<typeof ApplicationQuestionsSchema>;
