import {format} from 'date-fns';

export const getUTCDate = (dateString: string): Date => {
  const date = new Date(dateString);

  return new Date(
    date.getUTCFullYear(),
    date.getUTCMonth(),
    date.getUTCDate(),
    date.getUTCHours(),
    date.getUTCMinutes(),
    date.getUTCSeconds(),
  );
};

export const formatDate = (date: Date) => format(date, 'MMM d, yyyy');
