import {Record, String, Static, Optional, Null} from 'runtypes';
import {AgencySchema} from './agency';
import {BrokerSchema} from './broker';

export const W2RAssociationSchema = Record({
  id: String,
  wholesale_agency_id: String,
  wholesale_broker_id: String,
  retail_agency_id: String,
  retail_broker_id: String,
  status: String,
  line: String,
  wholesale_broker: Optional(BrokerSchema.Or(Null)),
  retail_broker: Optional(BrokerSchema.Or(Null)),
  wholesale_agency: Optional(AgencySchema.Or(Null)),
  retail_agency: Optional(AgencySchema.Or(Null)),
});

export type W2RAssociation = Static<typeof W2RAssociationSchema>;
