import * as React from 'react';
import {useFela} from 'react-fela';
import {Typography as T} from '@crucible-risk/typography';
import {Container} from '@crucible-risk/container';
import {Spacing} from '@crucible-risk/spacing';
import {CoalitionWhiteLogo} from './CoalitionWhiteLogo';

import {COPYRIGHT, FOOTER, LOGO, ROW} from './styles';

function getLogo(override_logo?: JSX.Element): JSX.Element {
  if (override_logo === undefined) {
    return <CoalitionWhiteLogo />;
  }
  return override_logo;
}

function getFooterBody(): JSX.Element {
  return (
    <T variant="bodyXSmall" weight="light" color="white" align="left">
      Insurance products are offered by Coalition Insurance Solutions
      Inc.(“CIS”), a licensed insurance producer and surplus lines broker, (Cal.
      license # 0L76155) acting on behalf of a number of unaffiliated insurance
      companies and an affiliated licensed insurance underwriter, Coalition
      Insurance Company (“CIC”) (NAIC # 29530). Insurance products offered
      through CIS and CIC may not be available in all states. Complete license
      information is available&nbsp;
      <T underline>
        <a
          href="https://www.coalitioninc.com/legal/licenses"
          target="_blank"
          rel="noopener noreferrer"
        >
          License Information
        </a>
      </T>
      &nbsp;
      <T underline>
        <a
          href="https://www.coalitioninc.com/legal/disclaimer"
          target="_blank"
          rel="noopener noreferrer"
        >
          Legal Disclaimers
        </a>
      </T>
      &nbsp;
      <T underline>
        <a
          href="https://www.coalitioninc.com/legal/privacy"
          target="_blank"
          rel="noopener noreferrer"
        >
          Privacy Policy
        </a>
      </T>
      &nbsp;
      <T underline>
        <a
          href="https://www.coalitioninc.com/legal/terms"
          target="_blank"
          rel="noopener noreferrer"
        >
          Terms of Use
        </a>
      </T>
      &nbsp; Copyright © 2023. All rights reserved. Coalition and the Coalition
      logo are trademarks of Coalition, Inc.
    </T>
  );
}

interface FooterProps {
  logo?: JSX.Element;
}

export const Footer = ({logo}: FooterProps) => {
  const {css} = useFela();

  // Ensure that the default logo is used, unless overwritten
  const footer_logo = getLogo(logo);
  const footer_body = getFooterBody();

  return (
    <div className={css(FOOTER)}>
      <Container>
        <Spacing top="64" bottom="64">
          <div className={css(ROW)}>
            <div className={css(LOGO)}>
              <Spacing top="16" bottom="16">
                {footer_logo}
              </Spacing>
            </div>
            <div className={css(COPYRIGHT)}>{footer_body}</div>
          </div>
        </Spacing>
      </Container>
    </div>
  );
};
