import React from 'react';
import {useFela} from 'react-fela';

import {typeVariants, fontWeights, colors} from '@crucible-risk/theme';

import {
  variantStyle,
  displayStyle,
  alignStyle,
  weightStyle,
  colorStyle,
  whiteSpaceStyle,
  transformStyle,
  underlineStyle,
} from './typography.fela';

export interface Props extends React.HTMLAttributes<HTMLDivElement> {
  /**
   * Text size variant. This prop controls size, height, and spacing.
   */
  variant?: keyof typeof typeVariants;

  /**
   * Render a flex or inline-flex element. This affects the component children,
   * but the not the element's overall layout.
   */
  flex?: boolean;

  /**
   * Display as a block element rather than the default inline and grow when
   * rendered within flex layouts.
   */
  fill?: boolean;

  /**
   * Prevent text within the element from wrapping.
   */
  nowrap?: boolean;

  /**
   * Prevent text within the element from wrapping and hide overflow text with
   * "..."
   */
  ellipsis?: boolean;

  /**
   * Transform the case of the text within the rendered element.
   */
  transform?: 'capitalize' | 'lowercase' | 'uppercase';

  /**
   * Control the internal `text-align` property. This will not have a visible
   * effect on inline `Typography` elements.
   */
  align?: 'left' | 'center' | 'right';

  /**
   * Set the font weight by name.
   */
  weight?: keyof typeof fontWeights;

  /**
   * Set the text color by name from the theme color list.
   */
  color?: keyof typeof colors;

  underline?: boolean;
}

export const Typography = (props: Props) => {
  const {
    variant,
    fill,
    flex,
    weight,
    align,
    color,
    nowrap,
    ellipsis,
    transform,
    underline,
    className,
    ...rest
  } = props;

  const {css} = useFela({
    variant,
    fill,
    flex,
    weight,
    align,
    color,
    nowrap,
    ellipsis,
    transform,
    underline,
  });

  const cn = [
    className,
    css(
      variantStyle,
      displayStyle,
      alignStyle,
      weightStyle,
      colorStyle,
      whiteSpaceStyle,
      transformStyle,
      underlineStyle,
    ),
  ]
    .filter(Boolean)
    .join(' ');

  return <div className={cn} {...rest} />;
};
