import * as React from 'react';
import {useHistory} from 'react-router-dom';
import {InsurancePolicy} from '@crucible-risk/sku-api-schema';
import {createClient} from '../../lib/api';
import {getSession} from '../../lib/session';
import {
  UnderwritingIncompleteError,
  UnknownErrorException,
  SecondaryReviewException,
} from '../../lib/exceptions';

export type UseQuoteProps = {
  sessionId?: string;
};

export type UseQuoteState = {
  inProgress: boolean;
  error?: Error;
  isSlow: boolean;
};

export type UseQuoteActions = {
  issueQuote: () => Promise<InsurancePolicy | void>;
};

export const useQuoteState = ({sessionId}: UseQuoteProps) => {
  const history = useHistory();
  const isMounted = React.useRef<boolean>(true);
  const inFlight = React.useRef<Promise<InsurancePolicy | void> | null>(null);
  const retryStartTime = React.useRef<number | null>(null);
  const [state, setState] = React.useState<UseQuoteState>({
    isSlow: false,
    inProgress: false,
  });

  React.useEffect(
    () => () => {
      isMounted.current = false;
      retryStartTime.current = null; // Reset retry timer on unmount
    },
    [],
  );

  const issueQuote = () => {
    if (inFlight.current) {
      return inFlight.current;
    }
    setState((prev) => ({...prev, inProgress: true, error: undefined}));
    const client = createClient(getSession(sessionId || ''));
    let complete = false;
    const timeout = setTimeout(() => {
      if (!complete && isMounted.current) {
        setState((prev) => ({...prev, isSlow: true}));
      }
    }, 5000);
    inFlight.current = client
      .createQuotation()
      .then((response) => {
        if (!response.ok) {
          if (response.status === 400) {
            // Handle JSON API error format for underwriting-incomplete
            if (
              (response.data as any)?.errors?.some(
                (error: any) => error.code === 'underwriting-incomplete',
              )
            ) {
              throw new UnderwritingIncompleteError(response.data);
            }
            throw new SecondaryReviewException(response);
          }
          throw new UnknownErrorException();
        }
        if (isMounted.current) {
          setState((prev) => ({...prev, inProgress: false}));
        }

        // Reset retry timer on successful response
        retryStartTime.current = null;

        return response.data;
      })
      .catch((error) => {
        if (error instanceof UnderwritingIncompleteError) {
          // If underwriting isn't complete, retry for up to 5 minutes
          const now = Date.now();

          // Initialize retry start time if this is the first retry
          if (retryStartTime.current === null) {
            retryStartTime.current = now;
          }

          // Check if 5 minutes (300,000 ms) have elapsed
          const elapsedTime = now - retryStartTime.current;
          const maxRetryTime = 5 * 60 * 1000;

          if (elapsedTime < maxRetryTime) {
            inFlight.current = null; // Reset the inflight ref so we can try again
            return new Promise<InsurancePolicy | void>((resolve, reject) => {
              window.setTimeout(() => {
                issueQuote().then(resolve).catch(reject);
              }, 5000);
            });
          } else {
            window.Sentry?.withScope((scope) => {
              scope.setExtras({
                data: error.detail,
              });
              window.Sentry?.captureException(error);
            });

            history.push({
              pathname: history.location.pathname.replace(
                'confirmation',
                'error',
              ),
              search: history.location.search,
            });
            return Promise.resolve();
          }
        }

        if (isMounted.current) {
          setState((prev) => ({...prev, inProgress: false, error}));
        }

        if (error instanceof SecondaryReviewException) {
          window.Sentry?.withScope((scope) => {
            scope.setExtras({
              data: error.response.data,
            });
            window.Sentry?.captureException(error);
          });
          history.push({
            pathname: history.location.pathname.replace(
              'confirmation',
              'secondary-review',
            ),
            search: history.location.search,
          });
        }
        return Promise.resolve();
      })
      .finally(() => {
        complete = true;
        clearTimeout(timeout);
      });
    return inFlight.current;
  };

  const actions: UseQuoteActions = {
    issueQuote,
  };

  return [state, actions] as const;
};
