import {Record, String, Null, Array, Static, Optional} from 'runtypes';

import {BrokerSchema} from './broker';
import {AccountPackageSchema} from './accountPackage';

// see: https://github.com/crucible-risk/webserver/blob/87eec67/www/serializers/user.py#L24
const LimitedAgency = Record({
  uuid: String,
  name: String,
});

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/account.py#L119
export const AccountSchema = Record({
  agency: LimitedAgency,
  broker: BrokerSchema,
  company_name: String.Or(Null),
  created_at: String.Or(Null),
  uuid: String,
  packages: Optional(Array(AccountPackageSchema)),
  domains: Optional(Array(String)),
  company_address: Optional(
    Record({
      city: String,
      country: String,
      postal_code: String,
      state: String,
      street_line_1: String,
      street_line_2: String,
    }),
  ),
});

export type Account = Static<typeof AccountSchema>;
