import React from 'react';

import {FullscreenLoading} from '/component/base/FullscreenLoading';

interface ContextProps {
  loading: boolean;
  setLoading: any;
  message: string;
  setMessage: any;
}

// @ts-expect-error
const LoadingContext = React.createContext<ContextProps>();

interface ProviderProps {
  defaultMessage?: string;
  children: React.ReactNode;
}

export const LoadingProvider: React.FC<ProviderProps> = ({
  children,
  defaultMessage = 'LOADING',
}) => {
  const [loading, setLoading] = React.useState(false);
  const [message, setMessage] = React.useState(defaultMessage);
  const isMounted = React.useRef<boolean>(true);

  React.useEffect(
    () => () => {
      isMounted.current = false;
    },
    [],
  );

  React.useEffect(() => {
    // Reset loading message after load finishes.
    if (!loading) {
      setMessage(defaultMessage);
    }
  }, [loading, defaultMessage]);

  const value = React.useMemo(() => {
    return {loading, setLoading, message, setMessage};
  }, [loading, setLoading, message, setMessage]);

  return (
    <LoadingContext.Provider value={value}>
      <>
        {children}
        {loading && <FullscreenLoading message={message} />}
      </>
    </LoadingContext.Provider>
  );
};

export const useLoading = (): ContextProps => React.useContext(LoadingContext);
