import React from 'react';
import {useFela} from 'react-fela';

import {containerStyle, containerPaddingStyle} from './container.fela';

interface Props extends React.HTMLAttributes<HTMLDivElement> {}

export const ContainerRefComponent = (
  props: Props,
  ref: React.Ref<HTMLDivElement>,
): React.ReactElement | null => {
  const {css} = useFela();

  return (
    <div
      ref={ref}
      {...props}
      className={css(containerStyle, containerPaddingStyle)}
    />
  );
};

export const Container = React.forwardRef(ContainerRefComponent);

export type ContainerAttributes = JSX.LibraryManagedAttributes<
  typeof Container,
  Props
>;
