import React from 'react';
import {useFela} from 'react-fela';

import {Spacing} from '@crucible-risk/spacing';
import {Typography as T} from '@crucible-risk/typography';
import {Button} from '@crucible-risk/button';

import {POLICY_CONTAINER, CONTENT, CONTENT_ITEM, BUTTONS} from './styles';
import {SuccessPageType} from '../../lib/content';
import {formatDate} from '../../lib/date';
import {Redacted} from '../Redacted';

type PolicyDetailsProps = {
  content: SuccessPageType['details'];
  policyNumber: string | null;
  policyStart: Date;
  policyEnd: Date;

  onClickPolicy: () => void;
  onClickRiskAssessment: () => void;
  downloadingPolicy: boolean;
  downloadingRiskAssessment: boolean;
  hasPolicy: boolean;
  hasRiskAssessment: boolean;
};

export const PolicyDetails = ({
  content,
  policyNumber,
  policyStart,
  policyEnd,
  onClickPolicy,
  onClickRiskAssessment,
  downloadingPolicy,
  downloadingRiskAssessment,
  hasPolicy,
  hasRiskAssessment,
}: PolicyDetailsProps) => {
  const {css} = useFela();

  return (
    <div className={`bg-panel ${css(POLICY_CONTAINER)}`}>
      <Spacing vertical="40" horizontal="24">
        <Spacing bottom="8">
          <T
            className="h3 fg-title"
            variant="displayXSmall"
            fill
            weight="semibold"
            align="center"
            color="black"
          >
            {content.heading}
          </T>
        </Spacing>
        <Spacing around="8">
          <div className={css(CONTENT)}>
            <div className={css(CONTENT_ITEM)}>
              <T className="body3 fg-title" weight="bold" variant="bodyRegular">
                {content.policyNumber}&nbsp;
              </T>
            </div>
            <div className={css(CONTENT_ITEM)}>
              <Redacted inline>
                <T className="body3 fg-title" variant="bodyRegular">
                  {policyNumber || '-'}
                </T>
              </Redacted>
            </div>
          </div>
          <div className={css(CONTENT)}>
            <div className={css(CONTENT_ITEM)}>
              <T className="body3 fg-title" weight="bold" variant="bodyRegular">
                {content.effectiveDate}&nbsp;
              </T>
            </div>
            <div className={css(CONTENT_ITEM)}>
              <T className="body3 fg-title" variant="bodyRegular">
                {formatDate(policyStart)}&nbsp;-&nbsp;
                {formatDate(policyEnd)}
              </T>
            </div>
          </div>
        </Spacing>
        <Spacing top="16">
          <div className={css(BUTTONS)}>
            {hasPolicy && (
              <Button
                className="fg-inverted bg-primary"
                fill
                size="small"
                onClick={onClickPolicy}
                loading={downloadingPolicy}
                sharpCorners
              >
                {content.policyButton}
              </Button>
            )}
            {hasRiskAssessment && (
              <Button
                className="fg-inverted bg-primary"
                fill
                size="small"
                onClick={onClickRiskAssessment}
                loading={downloadingRiskAssessment}
                sharpCorners
              >
                {content.riskAssessmentButton}
              </Button>
            )}
            {!hasRiskAssessment && !hasPolicy && (
              <div className={css(CONTENT_ITEM)}>
                <T className="body3 fg-title" variant="bodyRegular">
                  Congratulations on purchasing your Coalition cyber insurance
                  policy. You will recieve an email from{' '}
                  <b>join@coalitioninc.com</b> to access your free security
                  tools and policy documentation.
                </T>
              </div>
            )}
          </div>
        </Spacing>
      </Spacing>
    </div>
  );
};
