import * as React from 'react';
import {ApplicationQuestions} from '@crucible-risk/sku-api-schema';
import {useSkuApi} from '../../hooks/useSkuApi';
import {isJSONAPIErrorResponse, extractErrorDetails} from '/lib/errors';
import {APIResponseUnhandledError} from '/lib/exceptions';
import {toast} from 'react-hot-toast';

export type ApplicationQuestion = ApplicationQuestions['application_questions'][0];

export interface UseApplicationQuestionsStateProps {
  sessionId?: string;
  initialQuestions: ApplicationQuestions;
}

interface ApplicationQuestionsActions {
  getInFlight: () => Promise<void>;
  /**
   * Update answer without submitting to API
   */
  updateAnswer: (question: ApplicationQuestion, answer: string) => void;
  /**
   * Save question by patch request to API
   */
  saveQuestion: (question: ApplicationQuestion) => Promise<void>;
}

const mapQuestionToAnswer = (question: ApplicationQuestion) => {
  return {
    id: question.id,
    answer_text: question.answer_text,
    question_text: question.question_text,
    required: question.required,
    answer_options: undefined,
  };
};

export const useApplicationQuestionsState = ({
  sessionId,
  initialQuestions,
}: UseApplicationQuestionsStateProps) => {
  const isMounted = React.useRef<boolean>(true);
  const [, api] = useSkuApi({session: sessionId});
  const inFlight = React.useRef<Promise<void> | null>(null);
  const [status, setStatus] = React.useState<'incomplete' | 'complete'>(
    initialQuestions.status,
  );
  const [data, setData] = React.useState<
    ApplicationQuestions['application_questions']
  >(initialQuestions.application_questions);
  const [activity, setActivity] = React.useState<Record<string, boolean>>({});
  const [dirty, setDirty] = React.useState<Record<string, boolean>>({});
  const [busy, setBusy] = React.useState<boolean>(false);
  const [error, setError] = React.useState<Error | null>(null);

  // Store the last known good state
  const lastGoodState = React.useRef<
    ApplicationQuestions['application_questions']
  >(initialQuestions.application_questions);

  React.useEffect(
    () => () => {
      isMounted.current = false;
    },
    [],
  );

  const state = {
    error,
    busy,
    dirty,
    questions: data,
    complete: status === 'complete',
    activity,
  };

  const actions: ApplicationQuestionsActions = {
    getInFlight: async () => {
      if (inFlight.current) {
        return await inFlight.current;
      }
      return await Promise.resolve();
    },

    updateAnswer: (question: ApplicationQuestion, answer: string) => {
      setDirty((prev) => ({
        ...prev,
        [question.id]: true,
      }));
      setData((prev) =>
        prev.map((q) => {
          if (q.id === question.id) {
            return {
              ...q,
              answer_text: answer,
            };
          }
          return q;
        }),
      );
    },

    saveQuestion: async (question: ApplicationQuestion) => {
      if (inFlight.current) {
        return await inFlight.current;
      }

      setActivity((prev) => ({...prev, [question.id]: true}));
      setBusy(true);

      const updatedData = data.map((q) => {
        if (q.id === question.id) {
          return {...q, answer_text: question.answer_text};
        }
        return q;
      });

      const promise = api
        .answerApplicationQuestions(updatedData.map(mapQuestionToAnswer))
        .then((response) => {
          if (isMounted.current) {
            const newData = response.application_questions.filter(
              (q) => q.required,
            );
            setData(newData);
            setStatus(response.status);
            // Update last good state
            lastGoodState.current = newData;
          }
        })
        .catch((err) => {
          if (isMounted.current) {
            // Reset to last good state
            setData(lastGoodState.current);

            // Present a toast message if the backend returns a validation error
            if (err instanceof APIResponseUnhandledError) {
              const data = err.response.data;

              if (isJSONAPIErrorResponse(data)) {
                extractErrorDetails(data).forEach(([key, msg]) => {
                  toast.error(
                    <div>
                      <b>{key}</b>
                      <br />
                      {msg}
                    </div>,
                  );
                });
              }
            }

            setError(err);
          }
        })
        .finally(() => {
          if (isMounted.current) {
            setBusy(false);
            setActivity((prev) => {
              const {[question.id]: _, ...newActivity} = prev;
              return newActivity;
            });
          }
          inFlight.current = null;
        });
      inFlight.current = promise;
      return await promise;
    },
  };

  return [state, actions] as const;
};
