import React from 'react';

import {FocusScope, FocusScopeOptions} from './focusScope';

export function useFocusScope(options: FocusScopeOptions = {}, active = true) {
  const instanceRef = React.useRef<FocusScope>();
  instanceRef.current?.setOptions(options);

  const optionsRef = React.useRef(options);
  optionsRef.current = options;

  const elementRef = React.useRef<HTMLElement | null>(null);
  const activeRef = React.useRef(active);

  const update = (nextElement: HTMLElement | null, nextActive: boolean) => {
    // Handle target element changes.
    const targetElementChanged = nextElement !== elementRef.current;
    elementRef.current = nextElement;

    const activeStateChanged = nextActive !== activeRef.current;
    activeRef.current = nextActive;

    if (targetElementChanged || activeStateChanged) {
      // Remove FocusScope instance when deactivated or when the target
      // element changes.
      if (instanceRef.current) {
        // In the case that the focus scope is closing and contains the
        // current focused element, restore focus to the element focused
        // before the focus scope was created.
        const restoreFocus =
          !nextElement &&
          instanceRef.current.element.contains(document.activeElement);

        instanceRef.current.remove(restoreFocus);

        instanceRef.current = undefined;
      }

      // Create a new FocusScope instance when a new element is received.
      if (nextElement && nextActive) {
        instanceRef.current = new FocusScope(nextElement, optionsRef.current);
      }
    }
  };

  update(elementRef.current, active);

  // Create a custom function ref to be provided to the target element by the
  // consumer. It is called with a DOM node on first mount or in cases when the
  // target element changes and with null when the consumer component unmounts.
  return React.useCallback((element) => update(element, activeRef.current), []);
}
