import React, {Fragment, useEffect} from 'react';
import {useFela} from 'react-fela';

import {TextInput} from '@crucible-risk/text-input';
import {Spinner} from '@crucible-risk/spinner';

import {ChangeFunction, SaveFunction, Question} from './ApplicationQuestions';
import {QuestionInputSet} from './EditView';
import {Hr} from '../Hr';
import {childQuestions} from './child-questions';
import {removeCommas} from '../MonetaryInput';
import {isNumber} from '../../utils/numbers';
import {formatNumber} from '../../utils/intl';
import {INPUT_COLUMN, INPUT_ROW} from './styles';

interface TextInputQuestionProps {
  disabled: boolean;
  question: Question;
  onChange: ChangeFunction;
  onSave: SaveFunction;
  questionInfo: Record<string, string>;
  companyName: string;
  active: boolean;
}

export const TextInputQuestion: React.FC<TextInputQuestionProps> = ({
  question,
  disabled,
  onChange,
  onSave,
  questionInfo,
  companyName,
  active,
}) => {
  const {css} = useFela();

  const [displayValue, setDisplayValue] = React.useState('');

  useEffect(() => {
    const answer =
      question.answer_text && !isNumber(question.answer_text)
        ? ''
        : String(question.answer_text);

    setDisplayValue(
      !answer || answer === ''
        ? answer
        : formatNumber(parseInt(answer, 10), {}),
    );
  }, [question.answer_text]);

  const handleChange = (value: string) => {
    const newValue = removeCommas(value);

    if (!isNumber(newValue)) {
      if (newValue === '') {
        setDisplayValue('');
        onChange(question, newValue);
      }
      return;
    }

    setDisplayValue(formatNumber(parseInt(newValue, 10), {}));
    onChange(question, newValue);
  };

  const handleBlur = () => {
    onSave(question);
  };

  return (
    <Fragment key={question.id}>
      {!childQuestions[question.id] && <Hr />}

      <QuestionInputSet
        companyName={companyName}
        questionInfo={questionInfo}
        question={question}
        inputs={
          <div className={css(INPUT_ROW)}>
            <div className={css(INPUT_COLUMN)} style={{flexGrow: 1}}>
              <TextInput
                size="small"
                disabled={disabled}
                intent="neutral"
                value={displayValue}
                onChange={handleChange}
                onBlur={handleBlur}
              />
            </div>
            <div
              className={css(INPUT_COLUMN)}
              style={{alignSelf: 'center', minWidth: 16}}
            >
              {active && <Spinner size={0} />}
            </div>
          </div>
        }
      />
    </Fragment>
  );
};
