import React from 'react';

export interface State {
  pageError?: string;
  stripeError?: string;
}

function useStateManager() {
  const [state, setState] = React.useState<State>({
    pageError: undefined,
    stripeError: undefined,
  });

  const stateRef = React.useRef(state);
  stateRef.current = state;

  const actions = React.useMemo(
    () => ({
      setPageError(message?: string) {
        setState({
          ...stateRef.current,
          pageError: message,
        });
      },

      setStripeError(message?: string) {
        setState({
          ...stateRef.current,
          stripeError: message,
        });
      },
    }),
    [],
  );

  return {state, actions};
}

export const CheckoutContext = React.createContext<
  ReturnType<typeof useStateManager> | undefined
>(undefined);

export const CheckoutContextProvider: React.FC = ({children}) => {
  const context = useStateManager();

  return (
    <CheckoutContext.Provider value={context}>
      {children}
    </CheckoutContext.Provider>
  );
};

export function useCheckoutContext() {
  const context = React.useContext(CheckoutContext);

  if (!context) {
    throw new Error('Checkout context provider is missing');
  }

  return context;
}
