import {Record, String, Null, Static, Optional, Array} from 'runtypes';
import {AgencyFastSchema} from './agencyFast';

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/broker.py#L14
export const BrokerSchema = Record({
  email: String,
  external_id: Optional(String.Or(Null)),
  name: String.Or(Null),
  uuid: String,
  roles: Optional(Array(String)),
  agency: Optional(AgencyFastSchema.Or(Null)),
  agency_id: Optional(String),
});

export type Broker = Static<typeof BrokerSchema>;
