import React from 'react';
import {useFela} from 'react-fela';

import {Dialog} from '@crucible-risk/dialog';
import {Button} from '@crucible-risk/button';
import {Spacing} from '@crucible-risk/spacing';
import {Typography} from '@crucible-risk/typography';
import {BUTTONS} from './styles';

export type FTFModalContent = {
  body?: string;
  cancelButton?: string;
  continueButton?: string;
};

interface FtfRemovalDialogProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  onContinue: () => Promise<void>;
  content?: FTFModalContent;
}

export const FtfRemovalDialog: React.FC<FtfRemovalDialogProps> = ({
  open,
  setOpen,
  onContinue,
  content,
}) => {
  const {css} = useFela();
  return open ? (
    <Dialog shade open={open} size="regular" trapFocus>
      <Spacing around="48">
        <Spacing bottom="40">
          <Typography
            fill
            className="body3 fg-body"
            align="center"
            weight="semibold"
          >
            {content?.body ??
              'Are you sure? A dual control process is required in order to be eligible for Funds Transfer Fraud.'}
          </Typography>
        </Spacing>
        <div className={css(BUTTONS)}>
          <Button
            className="fg-inverted bg-primary"
            onClick={() => void onContinue()}
            size="small"
            sharpCorners
          >
            {content?.continueButton ?? 'Continue without FTF coverage'}
          </Button>
          <Button
            className="outline-primary border-primary fg-primary bg-panel"
            outline
            background
            size="small"
            onClick={() => {
              setOpen(false);
            }}
            sharpCorners
          >
            {content?.cancelButton ?? 'Edit my response'}
          </Button>
        </div>
      </Spacing>
    </Dialog>
  ) : null;
};
