import React from 'react';
import {ApplicationQuestions as _ApplicationQuestions} from '@crucible-risk/sku-api-schema';

import {FTFModalContent} from '../FtfRemovalDialog';

import {EditView} from './EditView';

export type Question = _ApplicationQuestions['application_questions'][0];

export type Questions = Question[];

export type ChangeFunction = (question: Question, answer: string) => void;
export type SaveFunction = (question: Question) => void;

export const getQuestionType = (q: Question): string => {
  if (q.input_type === 'radio') {
    if (q.answer_options?.some((opt) => opt.value === 'Yes') === true) {
      return 'yesno';
    }
  }

  return q.input_type ?? 'select';
};

interface Props {
  /**
   * Toggle editing mode for the questions
   * @default false
   */
  isEditing?: boolean;
  submitting: boolean;
  hasFTF: boolean;
  onRemoveDualControl: () => Promise<void>;
  onChange: ChangeFunction;
  onSave: SaveFunction;
  questions: Questions;
  questionInfo: Record<string, string>;
  content: FTFModalContent;
  companyName: string;
  activity: Record<string, boolean>;
}

export const ApplicationQuestions = ({
  isEditing = false,
  submitting,
  hasFTF,
  onRemoveDualControl,
  onChange,
  onSave,
  questions,
  questionInfo,
  content,
  companyName,
  activity,
}: Props) => {
  return (
    <EditView
      hasFTF={hasFTF}
      onRemoveDualControl={onRemoveDualControl}
      questionInfo={questionInfo}
      onChange={onChange}
      onSave={onSave}
      questions={questions}
      submitting={submitting}
      content={content}
      companyName={companyName}
      activity={activity}
    />
  );
};

ApplicationQuestions.displayName = 'ApplicationQuestions';
