import React from 'react';

import {Dialog} from '@crucible-risk/dialog';
import {Button} from '@crucible-risk/button';
import {CloseIcon} from '@crucible-risk/icon';
import {Spacing} from '@crucible-risk/spacing';
import {Typography} from '@crucible-risk/typography';

interface InfoDialogProps {
  open: boolean;
  setOpen: (open: boolean) => void;
  questionKey: string;
  questionInfo: Record<string, string>;
}

export const InfoDialog: React.FC<InfoDialogProps> = ({
  open,
  setOpen,
  questionKey,
  questionInfo,
}) => {
  if (questionInfo[questionKey]) {
    return (
      <Dialog
        shade
        open={open}
        size="small"
        trapFocus
        onClose={() => setOpen(false)}
        closeButton={
          <Button
            size="small"
            minimal
            intent="neutral"
            square
            onClick={() => setOpen(false)}
            sharpCorners
          >
            <CloseIcon aria-label="close dialog" />
          </Button>
        }
      >
        <Spacing around="48">
          <Typography className="body3 fg-title" align="center">
            {questionInfo[questionKey]}
          </Typography>
        </Spacing>
      </Dialog>
    );
  }
  return null;
};
