import React from 'react';

const cache = new Map<string, number>();

export function reset() {
  cache.clear();
}

function resolveIndex(prefix: string) {
  const next = cache.get(prefix) || 0;

  cache.set(prefix, next + 1);

  return next;
}

export function useUniqueId(prefix = 'unique') {
  const prefixRef = React.useRef(prefix);
  const [index, setIndex] = React.useState(() => resolveIndex(prefix));

  const indexRef = React.useRef(index);
  indexRef.current = index;

  React.useEffect(() => {
    if (prefixRef.current !== prefix) {
      setIndex(resolveIndex(prefix));
      prefixRef.current = prefix;
    }
  }, [prefix]);

  return `${prefix}-${index}`;
}
