import {Record, Null, String, Optional, Static} from 'runtypes';

import {CurrencySchema} from './currency';

export const CoverageSchema = Record({
  coverage: String,
  subretention: CurrencySchema.Or(Null),
  sublimit: CurrencySchema.Or(Null),
  description: Optional(String),
});

export type Coverage = Static<typeof CoverageSchema>;
