// Technical debt: We need to integrate this functionality into the React
//   lifecycle so that we can update the UI to prompt the customer to enable
//   local data storage when `sessionStorage` throws an error.
// https://stackoverflow.com/questions/24456891/

export const storeSession = (session: string, jwt: string) => {
  sessionStorage.setItem('session-' + session, jwt);
};

export const getSession = (session: string): string => {
  // For the affinity_referrer route, we use a lack of a session to return a lack of a jwt for a request that does not require auth
  if (session === '') {
    return '';
  }

  const jwt = sessionStorage.getItem('session-' + session);
  if (!jwt) {
    throw new Error('no-session');
  }

  return jwt;
};

export const hasSession = (session: string) => {
  try {
    return typeof getSession(session) === 'string';
  } catch (_err: unknown) {
    return false;
  }
};

export const storeConfigurationId = (session: string, id: number) => {
  sessionStorage.setItem('conf-' + session, id.toString(10));
};

export const getConfigurationId = (session: string): number => {
  return parseInt(sessionStorage.getItem('conf-' + session) || '', 10);
};
