import React from 'react';
import {
  useHistory,
  Switch,
  Route,
  Redirect,
  RouteComponentProps,
} from 'react-router-dom';
import {IStyle} from 'fela';
import {useFela, ThemeProvider} from 'react-fela';
import {Helmet} from 'react-helmet';
import {Toaster} from 'react-hot-toast';

import {ContentProvider, useProgram} from '../ContentProvider';
import {createContentfulClient} from '../../lib/contentful-content';
import {LandingPage} from '../../pages/Landing';
import {GeneralInfoPage} from '../../pages/GeneralInfo';
import {ConfirmationPage} from '../../pages/Confirmation';
import {Page} from '../Page';
import {QuoteNotSupportedPage} from '../../pages/QuoteNotSupported';
import {SelectPlanPage} from '../../pages/SelectPlan';
import {CheckoutPage} from '../../pages/Checkout';
import {PageParams, SecureRoute} from '../../lib/routing';
import {ModalPortal, NotificationPortal} from '../../components/Portals';
import {SuccessPage} from '../../pages/Success';
import {SecondaryReviewPage} from '../../pages/SecondaryReview';
import {ErrorPage} from '../../pages/Error';
import {NotificationArea} from '../NotificationArea';
import {defaultTheme} from '../../lib/theme';
import {
  setAffinityReferrerUuid,
  useAffinityReferrerIdPromise,
} from '../../hooks/useAffinityReferrer';
import {Reflow} from '/component/util/Reflow';
import {SupportChatProvider} from '/component/util/SupportChatProvider';

const WELL: IStyle = {position: 'relative', zIndex: 1};

const ChromePagesRoutes = () => {
  const history = useHistory();
  const program = useProgram();
  const [referrerId, setReferrerId] = React.useState('');
  const [referrerUpdated, setReferrerUpdated] = React.useState(false);

  void useAffinityReferrerIdPromise(
    program?.partnership?.slug,
    program?.slug,
  ).then((uuid: string) => {
    setReferrerId(uuid);
  });

  const theme = React.useMemo(
    () => ({
      ...defaultTheme,
      ...(program.theme ?? {}),
    }),
    [program],
  );

  const programStyles = React.useMemo(() => {
    if (Boolean(program.stylesheet) || Boolean(program.fonts?.length)) {
      return (
        <Helmet>
          {Array.isArray(program.fonts) && program.fonts.length > 0
            ? program.fonts?.map((font) => (
                <link key={font} rel="stylesheet" href={font} />
              ))
            : null}
          {typeof program.stylesheet === 'string' &&
          program.stylesheet.length > 0 ? (
            <style type="text/css">{program.stylesheet}</style>
          ) : null}
        </Helmet>
      );
    }
    return null;
  }, [program.stylesheet, program.fonts]);

  React.useEffect(() => {
    if (referrerId) {
      setAffinityReferrerUuid(referrerId);
      setReferrerUpdated(true);
    }
  }, [referrerId]);

  if (!referrerUpdated) {
    return null;
  }

  const routes = (
    <Switch>
      <Route exact path="/:partnership/:program/general-info">
        <GeneralInfoPage programContent={program} />
      </Route>

      <SecureRoute exact path="/:partnership/:program/select-plan">
        <SelectPlanPage history={history} />
      </SecureRoute>

      <SecureRoute exact path="/:partnership/:program/confirmation">
        <ConfirmationPage history={history} />
      </SecureRoute>

      <SecureRoute exact path="/:partnership/:program/checkout">
        <CheckoutPage history={history} />
      </SecureRoute>

      <SecureRoute exact path="/:partnership/:program/success">
        <SuccessPage />
      </SecureRoute>

      <Route exact path="/:partnership/:program/quote-not-supported">
        <QuoteNotSupportedPage />
      </Route>

      <Route exact path="/:partnership/:program/secondary-review">
        <SecondaryReviewPage />
      </Route>

      <Route exact path="/:partnership/:program/error">
        <ErrorPage />
      </Route>

      <Route exact path="/:partnership/:program">
        {program.landingPage ? (
          <LandingPage />
        ) : (
          <Redirect
            to={`/${program.partnership.slug}/${program.slug}/general-info`}
          />
        )}
      </Route>
    </Switch>
  );

  return (
    <ThemeProvider theme={theme}>
      <>
        {programStyles}
        <Page
          mainLogoURL={
            program.partnership.logo
              ? `${program.partnership.logo.url}?h=64`
              : null
          }
          secondaryLogoURL={program.logo ? `${program.logo.url}?h=64` : null}
          coalitionBrandOnly={theme.coalitionBrandOnly ?? false}
        >
          <SupportChatProvider>{routes}</SupportChatProvider>
        </Page>
      </>
    </ThemeProvider>
  );
};

export const AppRoot: React.FC = () => {
  const {css} = useFela();
  const contentClient = React.useMemo(() => {
    return createContentfulClient();
  }, []);

  const content = (
    <Switch>
      <Route exact path="/reflow">
        <SupportChatProvider>
          <Reflow />
        </SupportChatProvider>
      </Route>
      <Route
        path="/:partnership/:program"
        render={({match}: RouteComponentProps<PageParams>) => (
          <ContentProvider
            contentClient={contentClient}
            partnership={match.params.partnership}
            program={match.params.program}
          >
            <Route path="/:partnership/:program">
              <ChromePagesRoutes />
            </Route>
          </ContentProvider>
        )}
      />
      <Route
        path="*"
        render={() => {
          return <div>Not found</div>;
        }}
      />
    </Switch>
  );

  return (
    <>
      <Helmet>
        <title>Affinity | Coalition Inc.</title>
        <meta
          name="viewport"
          content="width=device-width, initial-scale=1, minimum-scale=1"
        />
      </Helmet>
      <Toaster position="top-right" toastOptions={{duration: 7500}} />
      <NotificationPortal.Provider>
        <>
          <NotificationArea />
          {content}
        </>
      </NotificationPortal.Provider>
      <div className={css(WELL)}>
        <ModalPortal.Well />
      </div>
    </>
  );
};
