/**
 * Lifted from broker-dashboard:
 * https://github.com/crucible-risk/frontend/blob/master/module/app/broker-dashboard/src/utils/intl.ts
 */

function getCacheKey(locale: string, options: any) {
  const keys = Object.keys(options);

  const orderedOptions: any = {};

  keys.sort().forEach((key) => {
    orderedOptions[key] = options[key];
  });

  return locale.toLowerCase() + '.' + JSON.stringify(orderedOptions);
}

const numberCache: Record<string, Intl.NumberFormat> = {};

export function getNumberFormat(
  locale: string,
  options: Intl.NumberFormatOptions,
) {
  const key = getCacheKey(locale, options);

  if (numberCache[key] === undefined) {
    numberCache[key] = new Intl.NumberFormat(locale, options);
  }

  return numberCache[key];
}

const dateTimeCache: Record<string, Intl.DateTimeFormat> = {};

export function getDateTimeFormat(
  locale: string,
  options: Intl.DateTimeFormatOptions,
) {
  const key = getCacheKey(locale, options);

  if (dateTimeCache[key] === undefined) {
    dateTimeCache[key] = new Intl.DateTimeFormat(locale, options);
  }

  return dateTimeCache[key];
}

export function formatCurrency(
  value: number,
  options: {fractionDigits?: number; currency: string; compact?: boolean},
) {
  const {fractionDigits, currency, compact = false} = options;
  const isUSDollar = currency === 'USD';

  const symbol = options.compact ? (value >= 1000000 ? 'M' : 'K') : '';
  const factor = options.compact
    ? value >= 1000000
      ? value / 1000000
      : value / 1000
    : value;

  const formattedNumber =
    getNumberFormat('en-US', {
      style: 'currency',
      currency,
      currencyDisplay: isUSDollar ? 'symbol' : 'code',
      minimumFractionDigits: fractionDigits ?? 0,
      maximumFractionDigits: fractionDigits ?? (compact ? 2 : 0),
    }).format(factor) + symbol;

  return formattedNumber;
}

export function formatDate(
  value: Date,
  options: Intl.DateTimeFormatOptions = {},
) {
  return getDateTimeFormat('en-US', options).format(value);
}

export function formatNumber(
  value: number,
  options: {fractionDigits?: number; compact?: boolean},
) {
  const symbol = options.compact ? (value >= 1000000 ? 'M' : 'K') : '';
  const factor = options.compact
    ? value >= 1000000
      ? value / 1000000
      : value / 1000
    : value;

  return (
    getNumberFormat('en-US', {
      minimumFractionDigits: options.fractionDigits ?? 0,
      maximumFractionDigits:
        options.fractionDigits ?? (options.compact ? 2 : 0),
    }).format(factor) + symbol
  );
}
