import {InsurancePolicy} from '@crucible-risk/sku-api-schema';

import {ProgramType} from '/lib/content';
import {createClient} from '/lib/api';
import {getSession} from '/lib/session';
import {Preloader} from '/lib/withPreloadedDataPage';

interface LoaderProps {
  programContent: ProgramType;
}

export interface GeneralInfoPageProps {
  skuInsurancePolicy: InsurancePolicy | null;
  sessionId?: string;
}

export const generalInfoPageDataLoader: Preloader<
  GeneralInfoPageProps,
  LoaderProps
> = (
  query: URLSearchParams,
  {programContent},
): Promise<GeneralInfoPageProps> => {
  const sessionId = query.get('session');
  const client = createClient(
    (sessionId && getSession(sessionId)) || undefined,
  );

  return Promise.all([
    ...(sessionId
      ? [client.getInsurancePolicy().then((response) => response.data)]
      : []),
  ]).then(([insurancePolicy]) => {
    return {
      skuInsurancePolicy: (insurancePolicy as InsurancePolicy) || null,
      sessionId: sessionId || undefined,
    };
  });
};
