import React from 'react';
import {useFela} from 'react-fela';

import {Spacing} from '@crucible-risk/spacing';
import {Typography} from '@crucible-risk/typography';
import {useA11yKeyEvents} from '@crucible-risk/a11y-key-events-hook';

import {
  ChangeFunction,
  Question,
  getQuestionType,
  SaveFunction,
} from './ApplicationQuestions';
import {ModalPortal} from '../../components/Portals';
import {FtfRemovalDialog, FTFModalContent} from '../FtfRemovalDialog';
import {InfoDialog} from '../InfoDialog';
import {YesNoQuestion} from './YesNoQuestion';
import {SelectQuestion} from './SelectQuestion';
import {TextInputQuestion} from './TextInputQuestion';
import {TextAreaQuestion} from './TextAreaQuestion';
import {Redacted} from '/components/Redacted';
import {Interweave} from '/components/Interweave';

import {childQuestions} from './child-questions';

import {
  QUESTION_ROW,
  QUESTION_COLUMN,
  QUESTION_ROW_TEXTAREA,
  ANSWER_COLUMN,
  DIALOG_LINK,
} from './styles';

interface QuestionInputSetProps {
  question: Question;
  inputs: JSX.Element;
  textarea?: boolean;
  questionInfo: Record<string, string>;
  companyName: string;
}

export const redactQuestionText = (
  questionText: string,
  companyName: string,
) => {
  return (
    <Interweave
      content={questionText.split(companyName)}
      separator={<Redacted inline>{companyName}</Redacted>}
    />
  );
};

/**
 * Simple component to display the question and input field
 * @param question
 * @param input
 * @param textarea
 * @param companyName
 */
export const QuestionInputSet: React.FC<QuestionInputSetProps> = ({
  question,
  inputs,
  textarea = false,
  questionInfo,
  companyName,
}) => {
  const {css} = useFela();
  const [modalOpen, setModalOpen] = React.useState<boolean>(false);
  const [onKeyUp, onKeyDown] = useA11yKeyEvents();

  if (textarea) {
    return (
      <div className={css(QUESTION_ROW_TEXTAREA)}>
        <Spacing bottom="24" />

        {!!childQuestions[question.id] && <Spacing left="24" />}

        <div>
          <Typography className="body3 fg-body" variant="bodyRegular">
            {redactQuestionText(question.question_text, companyName)}
            {questionInfo[question.id] ? ' ' : ''}
          </Typography>

          {!!questionInfo[question.id] && (
            <div
              onKeyDown={onKeyDown}
              onKeyUp={onKeyUp}
              role="button"
              tabIndex={0}
              onClick={() => {
                setModalOpen(true);
              }}
              className={css(DIALOG_LINK)}
            >
              <Typography
                className="fg-primary body5"
                color="blue600"
                variant="bodySmall"
              >
                More info
              </Typography>
            </div>
          )}
          <Spacing bottom="16" />
        </div>

        <div className={css({width: '100%'})}>{inputs}</div>

        {modalOpen && (
          <ModalPortal.Sink>
            <InfoDialog
              open={modalOpen}
              setOpen={setModalOpen}
              questionKey={question.id}
              questionInfo={questionInfo}
            />
          </ModalPortal.Sink>
        )}

        <Spacing bottom="24" />
      </div>
    );
  }

  return (
    <div className={css(QUESTION_ROW)}>
      {!!childQuestions[question.id] && <Spacing left="24" />}

      <div className={css(QUESTION_COLUMN)}>
        {redactQuestionText(question.question_text, companyName)}
        {questionInfo[question.id] ? ' ' : ''}

        {!!questionInfo[question.id] && (
          <div
            onKeyDown={onKeyDown}
            onKeyUp={onKeyUp}
            role="button"
            tabIndex={0}
            onClick={() => {
              setModalOpen(true);
            }}
            className={css(DIALOG_LINK)}
          >
            <Typography
              className="body5 fg-primary"
              color="blue600"
              variant="bodySmall"
            >
              More info
            </Typography>
          </div>
        )}
      </div>

      <div className={css(ANSWER_COLUMN)}>{inputs}</div>

      {modalOpen && (
        <ModalPortal.Sink>
          <InfoDialog
            open={modalOpen}
            setOpen={setModalOpen}
            questionKey={question.id}
            questionInfo={questionInfo}
          />
        </ModalPortal.Sink>
      )}
    </div>
  );
};

const ftfQuestions = ['dual_control', 'dual_control_5k'];

const isFTFQuestion = (question: Question): boolean => {
  return ftfQuestions.includes(question.id);
};

interface Props {
  submitting: boolean;
  hasFTF: boolean;
  onRemoveDualControl: () => Promise<void>;
  onChange: ChangeFunction;
  onSave: SaveFunction;
  questions: Question[];
  questionInfo: Record<string, string>;
  content: FTFModalContent;
  companyName: string;
  activity: Record<string, boolean>;
}

export const EditView: React.FC<Props> = ({
  hasFTF,
  content,
  onRemoveDualControl,
  onChange,
  onSave,
  questions,
  submitting,
  questionInfo,
  companyName,
  activity,
}) => {
  const [ftfModalOpen, setFtfModalOpen] = React.useState<boolean>(false);

  return (
    <div>
      {ftfModalOpen && (
        <ModalPortal.Sink>
          <FtfRemovalDialog
            onContinue={() => {
              setFtfModalOpen(false);

              return onRemoveDualControl().then(() => {
                for (const q of questions.filter(isFTFQuestion)) {
                  onSave({...q, answer_text: 'No'});
                }
              });
            }}
            open={ftfModalOpen}
            setOpen={setFtfModalOpen}
            content={content}
          />
        </ModalPortal.Sink>
      )}

      {questions.map((question) => {
        const questionType = getQuestionType(question);

        switch (questionType) {
          case 'yesno':
            return (
              <YesNoQuestion
                companyName={companyName}
                questionInfo={questionInfo}
                disabled={submitting}
                key={question.id}
                currentQuestion={question}
                active={!!activity[question.id]}
                onChange={(q, answer) => {
                  // Unfornately we need some hacky code here to
                  // to handle the special scenario for the dual transfer case
                  // question and ftf
                  if (isFTFQuestion(q) && answer === 'No' && hasFTF) {
                    setFtfModalOpen(true);
                  } else {
                    onSave({...q, answer_text: answer});
                  }
                }}
              />
            );

          case 'text-input':
            return (
              <TextInputQuestion
                companyName={companyName}
                questionInfo={questionInfo}
                disabled={submitting}
                key={question.id}
                question={question}
                onChange={onChange}
                onSave={onSave}
                active={!!activity[question.id]}
              />
            );

          case 'text-area':
            return (
              <TextAreaQuestion
                companyName={companyName}
                questionInfo={questionInfo}
                disabled={submitting}
                key={question.id}
                question={question}
                onChange={onChange}
                onSave={onSave}
                active={!!activity[question.id]}
              />
            );

          default:
          case 'select':
            return (
              <SelectQuestion
                companyName={companyName}
                questionInfo={questionInfo}
                disabled={submitting}
                key={question.id}
                question={question}
                onChange={(q, answer) => onSave({...q, answer_text: answer})}
                active={!!activity[question.id]}
              />
            );
        }
      })}
    </div>
  );
};

QuestionInputSet.displayName = 'QuestionInputSet';
