import React from 'react';
import {useFela} from 'react-fela';

export const Redacted: React.FC<{inline?: boolean}> = ({
  children,
  inline = false,
}) => {
  const {css} = useFela();

  return (
    <div
      className={`fs-exclude ${css({
        display: inline ? 'inline-block' : undefined,
      })}`}
    >
      {children}
    </div>
  );
};
