import {Record, String, Array, Boolean, Static} from 'runtypes';

import {CurrencySchema} from './currency';

// see: https://github.com/crucible-risk/webserver/blob/0edb625/www/serializers/sku/invoice.py#L18
export const InvoiceSchema = Record({
  balance_total: CurrencySchema,
  balance_outstanding: CurrencySchema,
  price_breakdown: Array(
    Record({
      label: String,
      amount: CurrencySchema,
    }),
  ),
  paid: Boolean,
  payment_processor_public_key: String,
});

export type Invoice = Static<typeof InvoiceSchema>;
