import ResizeObserver from 'resize-observer-polyfill';
import {Rect, RectShape} from './rect';

import {resolver, ResolverResult, Region} from './resolver';

import {
  getContainingBlock,
  getClippingBlock,
  getContentRect,
  getViewportRect,
} from './util';

export interface Options {
  region?: Region;

  enableTop?: boolean;
  enableRight?: boolean;
  enableBottom?: boolean;
  enableLeft?: boolean;

  constrainTop?: boolean;
  constrainRight?: boolean;
  constrainBottom?: boolean;
  constrainLeft?: boolean;

  snapTop?: number[];
  snapRight?: number[];
  snapBottom?: number[];
  snapLeft?: number[];

  sticky?: boolean;
  matchTargetWidth?: boolean;

  overlap?: number;
  offset?: number;

  getContentRect?: (element: HTMLElement) => RectShape;
  getTargetRect?: (element: HTMLElement) => RectShape;
}

export interface LayoutResult extends ResolverResult {
  anchorPoint: {x: number; y: number};
  target: Rect;
  bounds: Rect;
}

export interface Callback {
  (result: LayoutResult | null): void;
}

function getBoundsRect(contentElement: HTMLElement) {
  const clippingBlockNode = getClippingBlock(contentElement.parentNode);
  const viewportRect = getViewportRect();
  const contentRect = getContentRect(clippingBlockNode);

  return Rect.intersect(viewportRect, contentRect);
}

function getAnchorPoint(contentElement: HTMLElement) {
  const containingBlockNode = getContainingBlock(contentElement.parentNode);
  const containingBlockRect = getContentRect(containingBlockNode);

  if (containingBlockNode === document.documentElement) {
    return {
      x: -window.pageXOffset,
      y: -window.pageYOffset,
    };
  }

  return {
    x: containingBlockRect.left - containingBlockNode.scrollLeft,
    y: containingBlockRect.top - containingBlockNode.scrollTop,
  };
}

const defaultSnap = [0, 0.5, 1];
const getElementRect = (element: HTMLElement) =>
  element.getBoundingClientRect();

class Config {
  options: Options;

  constructor(options: Options = {}) {
    this.options = options;
  }

  setOptions(options: Options = {}) {
    this.options = options;
  }

  get region() {
    return this.options.region;
  }

  get enableTop() {
    return this.options.enableTop ?? true;
  }
  get enableRight() {
    return this.options.enableRight ?? true;
  }
  get enableBottom() {
    return this.options.enableBottom ?? true;
  }
  get enableLeft() {
    return this.options.enableLeft ?? true;
  }

  get constrainTop() {
    return this.options.constrainTop ?? true;
  }
  get constrainRight() {
    return this.options.constrainRight ?? true;
  }
  get constrainBottom() {
    return this.options.constrainBottom ?? true;
  }
  get constrainLeft() {
    return this.options.constrainLeft ?? true;
  }

  get snapTop() {
    return this.options.snapTop ?? defaultSnap;
  }
  get snapRight() {
    return this.options.snapRight ?? defaultSnap;
  }
  get snapBottom() {
    return this.options.snapBottom ?? defaultSnap;
  }
  get snapLeft() {
    return this.options.snapLeft ?? defaultSnap;
  }

  get sticky() {
    return this.options.sticky ?? false;
  }
  get matchTargetWidth() {
    return this.options.matchTargetWidth ?? false;
  }

  get offset() {
    return this.options.offset ?? 0;
  }
  get overlap() {
    return this.options.overlap ?? 0;
  }

  get getContentRect() {
    return this.options.getContentRect ?? getElementRect;
  }
  get getTargetRect() {
    return this.options.getTargetRect ?? getElementRect;
  }
}

export class PopoverController {
  config: Config;
  targetElement: HTMLElement | null = null;
  contentElement: HTMLElement | null = null;
  targetObserver?: ResizeObserver;
  contentObserver?: ResizeObserver;
  targetConnected = false;
  contentConnected = false;
  callback?: Callback;

  lastRegion?: Region;
  lastAlign: Partial<Record<Region, number>> = {};
  lastTargetRect?: Rect;
  animationFrame = NaN;

  constructor(
    contentElement?: HTMLElement,
    targetElement?: HTMLElement,
    options?: Options,
    callback?: Callback,
  ) {
    this.config = new Config(options);

    if (contentElement) {
      this.setContent(contentElement);
    }

    if (targetElement) {
      this.setTarget(targetElement);
    }

    this.setCallback(callback);
  }

  setOptions = (options?: Options) => {
    this.config.setOptions(options);
  };

  _disconnectContent() {
    if (this.contentConnected) {
      // Reset internal state derived from previous content element.
      this.lastTargetRect = undefined;
      this.lastRegion = undefined;
      this.lastAlign = {};

      if (this.callback) {
        this.callback(null);
      }

      // Cancel any pending updates related to previous content element;
      window.cancelAnimationFrame(this.animationFrame);

      if (this.contentObserver) {
        this.contentObserver.disconnect();
      }

      this.contentConnected = false;
    }
  }

  _disconnectTarget() {
    if (this.targetConnected) {
      window.removeEventListener('scroll', this._handleScroll, true);
      window.removeEventListener('resize', this._handleResize);

      this.targetObserver?.disconnect();

      this.targetConnected = false;
    }
  }

  _connect() {
    if (this.contentElement && !this.contentConnected) {
      this.contentElement.style.position = 'absolute';
      this.contentElement.style.top = '-99999px';
      this.contentElement.style.left = '-99999px';

      const handleContentResize = () => {
        if (this.lastTargetRect) {
          this.update(this.lastTargetRect);
        } else if (this.targetElement) {
          this.update(this.config.getTargetRect(this.targetElement));
        }
      };

      this.contentObserver = new ResizeObserver(handleContentResize);
      this.contentObserver.observe(this.contentElement);

      handleContentResize();

      this.contentConnected = true;
    }

    if (this.targetElement && this.contentElement && !this.targetConnected) {
      window.addEventListener('scroll', this._handleScroll, true);
      window.addEventListener('resize', this._handleResize);

      const handleTargetResize = () => {
        if (this.targetElement) {
          this.update(this.config.getTargetRect(this.targetElement));
        }
      };

      this.targetObserver = new ResizeObserver(handleTargetResize);
      this.targetObserver.observe(this.targetElement);

      handleTargetResize();

      this.targetConnected = true;
    }
  }

  setContent = (contentElement: HTMLElement | null) => {
    if (contentElement === this.contentElement) {
      return;
    }

    this._disconnectContent();

    if (!contentElement) {
      this._disconnectTarget();
    }

    this.contentElement = contentElement;

    this._connect();
  };

  setTarget = (targetElement: HTMLElement | null) => {
    if (targetElement === this.targetElement) {
      return;
    }

    this._disconnectTarget();

    this.targetElement = targetElement;

    this._connect();
  };

  setCallback = (callback?: Callback) => {
    this.callback = callback;
  };

  _handleResize = () => {
    if (!this.targetElement) {
      return;
    }

    this.update(this.config.getTargetRect(this.targetElement));
  };

  _handleScroll = (event: Event) => {
    if (!this.targetElement) {
      return;
    }

    if (
      event.target === document ||
      (event.target instanceof HTMLElement &&
        event.target.contains(this.targetElement))
    ) {
      this.update(this.config.getTargetRect(this.targetElement));
    }
  };

  disconnect = () => {
    this.setContent(null);
    this.setTarget(null);
  };

  update = (target: RectShape) => {
    const targetRect = Rect.fromRect(target);

    if (!this.contentElement) {
      return;
    }

    this.lastTargetRect = targetRect;

    if (this.config.matchTargetWidth) {
      this.contentElement.style.width = targetRect.width + 'px';
    }

    window.cancelAnimationFrame(this.animationFrame);

    this.animationFrame = window.requestAnimationFrame(() => {
      if (!this.contentElement) {
        return;
      }

      const boundsRect = getBoundsRect(this.contentElement);
      const contentRect = this.config.getContentRect(this.contentElement);

      const result = resolver({
        offset: this.config.offset,
        edgeOffset: 0,
        overlap: this.config.overlap,
        align: this.config.sticky ? this.lastAlign : undefined,
        region:
          this.config.sticky && this.lastRegion
            ? this.lastRegion
            : this.config.region,
        bounds: boundsRect,
        target: targetRect,
        content: contentRect,
        enable: {
          top: this.config.enableTop,
          right: this.config.enableRight,
          bottom: this.config.enableBottom,
          left: this.config.enableLeft,
        },
        constrain: {
          top: this.config.constrainTop,
          right: this.config.constrainRight,
          bottom: this.config.constrainBottom,
          left: this.config.constrainLeft,
        },
        snap: {
          top: this.config.snapTop,
          right: this.config.snapRight,
          bottom: this.config.snapBottom,
          left: this.config.snapLeft,
        },
      });

      this.lastAlign[result.region] = result.align;
      this.lastRegion = result.region;

      const anchorPoint = getAnchorPoint(this.contentElement);

      this.contentElement.style.position = 'absolute';
      this.contentElement.style.top = '0';
      this.contentElement.style.left = '0';

      const x = Math.round(result.content.left - anchorPoint.x);
      const y = Math.round(result.content.top - anchorPoint.y);

      this.contentElement.style.transform = `translate3d(${x}px, ${y}px, 0)`;

      if (this.callback) {
        this.callback({
          ...result,
          anchorPoint,
          target: targetRect,
          bounds: boundsRect,
        });
      }
    });
  };
}
