import {createClient} from '/lib/api';
import {APIExceptionError} from '/lib/exceptions';

/**
 * useAffinityReferrerIdPromise
 * Fetches the referrer uuid from the Affinity-Customer-API-Gateway, based off the provided partner/program and session.
 */
export const usePartnerProgramPromise = async (uuid: string) => {
  // Since the affinity_referrer route is not part of a session (not part of a chain of customer-api request initiated
  // by creating a new policy) there is no reason to use the session framework. So, for this request we just use a
  // temp client with an empty auth, since auth is generated after a policy is made through customer-api.
  const client = createClient('');

  const resp = await client
    .getPartnerProgram(uuid)
    .then((response: {ok: boolean; status: number; data: any}) => {
      if (!response.ok) {
        throw new APIExceptionError('getPartnerProgram');
      }

      return String(response.data);
    })
    .catch(() => {
      throw new APIExceptionError('getPartnerProgram');
    });
  return resp;
};
