import React from 'react';
import {
  PopoverController,
  Options,
  Callback,
} from '@crucible-risk/popover-controller';

export function usePopover(
  /**
   * Popover configuration options. See `@crucible-risk/popover-controller` for
   * more details.
   */
  options?: Options,

  /**
   * Optional layout update handler. Use this to update the position of the
   * content element (this module does not make any dom updates on its own).
   */
  callback?: Callback,
) {
  const [instance] = React.useState(() => new PopoverController());

  instance.setOptions(options);
  instance.setCallback(callback);

  return instance;
}
