import React from 'react';

import {Container} from '@crucible-risk/container';
import {Spacing} from '@crucible-risk/spacing';
import {Flex} from '@crucible-risk/flex';
import {Typography as T} from '@crucible-risk/typography';
import {
  PatchIcon,
  ComputerErrorIcon,
  PasswordIcon,
  CoalitionIcon,
} from '@crucible-risk/icon';

import {PolicyDetails} from '../../PolicyDetails';
import {ContentPanel} from '../../ContentPanel';
import {SuccessPageType} from '../../../lib/content';

type SuccessPageProps = {
  content: SuccessPageType;
  policyNumber: string | null;
  policyStart: Date;
  policyEnd: Date;
  onClickPolicy: () => void;
  onClickRiskAssessment: () => void;
  downloadingPolicy: boolean;
  downloadingRiskAssessment: boolean;
  hasPolicy: boolean;
  hasRiskAssessment: boolean;
};

const iconForItem: {[key: string]: JSX.Element} = {
  Patch: <PatchIcon />,
  ComputerError: <ComputerErrorIcon />,
  Password: <PasswordIcon />,
};

export const SuccessPageView = ({
  content,
  policyNumber,
  policyStart,
  policyEnd,
  onClickPolicy,
  onClickRiskAssessment,
  downloadingPolicy,
  downloadingRiskAssessment,
  hasPolicy,
  hasRiskAssessment,
}: SuccessPageProps) => {
  return (
    <Container>
      <Spacing vertical="88">
        <Flex col align="center">
          <img src={content.image.url} alt="" style={{maxWidth: '60%'}} />
          <T
            className="h1 fg-title"
            variant="displayRegular"
            color="black"
            weight="semibold"
            fill
            align="center"
          >
            {content.heading}
          </T>
          <div style={{maxWidth: '800px'}}>
            <Spacing vertical="24">
              <T
                className="body1 fg-body"
                variant="bodyXLarge"
                fill
                align="center"
              >
                {content.body}
              </T>
            </Spacing>
          </div>
        </Flex>
        <Spacing vertical="32">
          <Flex col align="center">
            <PolicyDetails
              content={content.details}
              policyNumber={policyNumber}
              policyEnd={policyEnd}
              policyStart={policyStart}
              onClickPolicy={onClickPolicy}
              onClickRiskAssessment={onClickRiskAssessment}
              downloadingPolicy={downloadingPolicy}
              downloadingRiskAssessment={downloadingRiskAssessment}
              hasPolicy={hasPolicy}
              hasRiskAssessment={hasRiskAssessment}
            />
          </Flex>
        </Spacing>
        <Spacing vertical="32">
          <ContentPanel.Divider />
        </Spacing>
        <Spacing vertical="16">
          <ContentPanel
            title={content.footer.heading}
            description={content.footer.body}
          >
            <ContentPanel.Row3Items
              content={content.footer.content.map((item) => (
                <ContentPanel.Item
                  title={item.heading}
                  description={item.body}
                  icon={iconForItem[item.icon] || <CoalitionIcon />}
                />
              ))}
            />
          </ContentPanel>
        </Spacing>
      </Spacing>
    </Container>
  );
};

SuccessPageView.displayName = 'SuccessPageView';
