import React from 'react';

import {Container} from '@crucible-risk/container';
import {Spacing} from '@crucible-risk/spacing';
import {Typography as T} from '@crucible-risk/typography';
import {Configuration} from '@crucible-risk/sku-api-schema';

import {ContentPanel} from '../../ContentPanel';
import {PlanCards, PlanCard} from '../../PlanCard';
import {TextBanner} from '../../TextBanner';
import {Steps} from '../../Steps';
import {SelectPlanPageType} from '../../../lib/content';
import {Icon} from '../../Icon';
import {FTFDialog} from '../../PlanCard/FTFDialog';
import {ModalPortal} from '../../../components/Portals';
import {Alert} from '/components/Alert';

import {DefaultSection1Head, DefaultSection1Body} from './defaults';

interface SelectPlanPageViewProps {
  configurations: Configuration[];
  content: SelectPlanPageType;
  onSelect: (id: number) => void;
  submitting: boolean;
  error?: Error;
  selectedId?: number;
  submittingId?: number;
  ftfConfigurations?: {
    withoutFTF: Configuration;
    withFTF: Configuration;
  };
  onFTFClose: () => void;
  onOpenContact: () => void;
}

export const SelectPlanPageView = ({
  configurations,
  content,
  onSelect,
  submitting,
  error,
  selectedId,
  submittingId,
  ftfConfigurations,
  onFTFClose,
  onOpenContact,
}: SelectPlanPageViewProps) => {
  const handleSelectCard = (id: number) => () => {
    onSelect(id);
  };

  return (
    <Container>
      <Spacing bottom="56" />
      <Steps>
        <Steps.Step title="General Info" status="finished" />
        <Steps.Step title="Select a Plan" status="active" />
        <Steps.Step title="Confirmation" />
        <Steps.Step title="Checkout" />
      </Steps>
      <Spacing bottom="56" />
      <h1>
        <T
          className="h1 fg-title"
          variant="displaySmall"
          fill
          align="center"
          weight="semibold"
          color="black"
        >
          {content.heading}
        </T>
      </h1>
      <Spacing bottom="32" />
      <Alert error={error} onOpenContact={onOpenContact} />
      <PlanCards
        cards={configurations
          .filter((configuration) => {
            return !configuration.base_configuration_id;
          })
          .map((configuration, index) => {
            return (
              <PlanCard
                isRecommended={index === 1}
                key={configuration.id}
                configuration={configuration}
                content={content.card}
                onSelect={handleSelectCard(configuration.id)}
                selectedId={selectedId}
                submittingId={submittingId}
                submitting={submitting}
              />
            );
          })}
      />
      <Spacing bottom="80" />
      <ContentPanel.Divider />
      <Spacing bottom="32" />
      <TextBanner
        title={
          content.body.heading ? content.body.heading : DefaultSection1Head
        }
        description={
          content.body.body ? content.body.body : DefaultSection1Body
        }
      />
      <Spacing bottom="48" />
      <ContentPanel title={content.coveragesHeader} />
      <ContentPanel>
        <ContentPanel.Row3Items
          content={content.coverages.map((coverageContent) => {
            return (
              <ContentPanel.Item
                title={coverageContent.heading}
                description={coverageContent.body}
              />
            );
          })}
        />
      </ContentPanel>
      <Spacing bottom="32" />
      <ContentPanel.Divider />
      <Spacing bottom="32" />
      <ContentPanel
        title={content.footer.heading}
        description={content.footer.body}
      >
        <ContentPanel.Row3Items
          content={content.footer.content.map((footerItemContent) => {
            return (
              <ContentPanel.Item
                icon={<Icon icon={footerItemContent.icon} />}
                title={footerItemContent.heading}
                description={footerItemContent.body}
              />
            );
          })}
        />
      </ContentPanel>
      <Spacing bottom="32" />
      {ftfConfigurations && (
        <ModalPortal.Sink>
          <FTFDialog
            content={content.modal}
            ftfConfigurations={ftfConfigurations}
            onSelect={onSelect}
            submittingId={submittingId}
            submitting={submitting}
            onClose={onFTFClose}
          />
        </ModalPortal.Sink>
      )}
    </Container>
  );
};
