import React from 'react';
import {render} from 'react-dom';

export const DEFAULT_MESSAGE =
  'Something went wrong loading the page. This error has been reported.';

export interface RegisterGlobalErrorHandlerArgs {
  /**
   * The error handler that is called when an error occurs.
   * The passed error argument is _likely_ to be an Error object
   * but not guaranteed.
   * Recommended to use this to send the error to sentry.
   */
  onError?: (error: any) => void;
  /**
   * The view that is displayed when an error occurs.
   * The passed error prop is _likely_ to be an Error object
   * but not guaranteed.
   */
  ErrorView?: React.ComponentType<{error: any}>;
}

/**
 * Simple default error view which can be tested against
 */
const DefaultErrorView = () => {
  return (
    <div
      data-testid="error-handler"
      style={{
        width: '100vw',
        height: '100vh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
      }}
    >
      {DEFAULT_MESSAGE}
    </div>
  );
};

/**
 * Function to register a global error handler.
 * Returns a function to unregister the handler.
 *
 * Error handler will render an error to the specified render element
 * when an error uncaught error is thrown.
 */
export const registerGlobalErrorHandler = (
  renderElement: Element | null,
  args: RegisterGlobalErrorHandlerArgs = {},
) => {
  const {onError, ErrorView = DefaultErrorView} = args;
  const errorHandler = (e: ErrorEvent) => {
    // Call custom event handler, if specified
    onError?.(e.error);
    e.stopImmediatePropagation();
    e.preventDefault();

    render(<ErrorView error={e.error} />, renderElement);
  };

  window.addEventListener('error', errorHandler);

  return function unregisterGlobalErrorHandler() {
    window.removeEventListener('error', errorHandler);
  };
};
