import React from 'react';

interface Props extends React.SVGProps<SVGSVGElement> {
  /**
   * Icon accessibility label. This is set by default to be the name of the icon
   * e.g. `<ArrowRightIcon>` will have the label "arrow right icon."
   *
   * @default [icon name]
   */
  label: string;

  /**
   * Icon size.
   *
   * @default 24
   */
  size?: number;
}

export const Icon = (props: Props) => {
  const {label, size = 24, ...rest} = props;

  return (
    <svg
      aria-label={label}
      fill="currentColor"
      focusable={false}
      {...rest}
      viewBox="0 0 24 24"
      width={size}
      height={size}
    />
  );
};
