import * as React from 'react';
import merge from 'lodash/merge';

export type FormValues = {};

export type FormFieldValue<T> = T[keyof T];

export type FormFlags<T extends FormValues> = {
  [K in keyof Partial<T>]: boolean;
};

export type ValidationErrors<T extends FormValues> = {
  [K in keyof Partial<T>]: string;
};

export type SetFieldValidity<T> = (field: keyof T, isValid: boolean) => void;

export type ValidateForm = () => boolean;

export type SetValues<T extends FormValues> = (values: Partial<T>) => void;

export type FormChangeHandler<T extends FormValues> = (
  field: keyof T,
  value: T[keyof T],
) => void;

export type FormBlurHandler<T extends FormValues> = (field: keyof T) => void;

export type GetFormOutput<U> = () => U;

export type FormActions<T, U> = {
  /**
   * Manually set a field validity flag (for external validation, for example)
   */
  setFieldValidity: SetFieldValidity<T>;
  /**
   * Field onChange handler
   */
  // @ts-expect-error
  handleChange: FormChangeHandler<T>;
  /**
   * Field onBlur handler
   */
  // @ts-expect-error
  handleBlur: FormBlurHandler<T>;
  /**
   * Maps field values into output type
   */
  getOutput: GetFormOutput<U>;
  validateForm: ValidateForm;
  // @ts-expect-error
  setValues: SetValues<T>;
  // @ts-expect-error
  setErrors: SetValues<T>;
};

type Validation = {
  valid: boolean;
  error?: string;
};

export type useFormProps<T, U> = {
  initialValues: Partial<T>;
  /**
   * Verifies that a given form is valid
   */
  validate?: (key: keyof T, value: T[keyof T], values: T) => Validation;
  /**
   * Transforms a given form value into type R (onBlur)
   */
  transform?: (key: keyof T, value: T[keyof T]) => T[keyof T];
  /**
   * Maps the internal form state T into output type R
   */
  map: (values: T) => U;
  /**
   * Force validations to run on mount
   */
  validateOnMount?: boolean;
  /**
   * Default values that are applied to any partial values
   */
  defaultValues: T;
};

const defaultValidateFn = <T, R>(_key: keyof T, _value: R) => {
  return {valid: true, error: undefined};
};

const defaultTransformFn = <T, R>(key: keyof T, value: R) => {
  return value;
};

export const useForm = <T extends FormValues, U>(props: useFormProps<T, U>) => {
  const {
    validate = defaultValidateFn,
    transform = defaultTransformFn,
    map,
    initialValues,
    validateOnMount = false,
    defaultValues,
  } = props;
  const needsValidation = React.useRef<boolean>(validateOnMount);
  const [dirty, setDirty] = React.useState<Partial<FormFlags<T>>>({});
  const [valid, setValid] = React.useState<Partial<FormFlags<T>>>({});
  const [errors, setErrors] = React.useState<Partial<ValidationErrors<T>>>({});
  const [values, setValues] = React.useState<T>({
    ...defaultValues,
    ...initialValues,
  });

  const formIsValid = React.useMemo(() => {
    return !Object.values(valid).some((v) => v === false);
  }, [valid]);

  const formIsDirty = React.useMemo(() => {
    return Object.values(dirty).some((d) => d === true);
  }, [dirty]);

  React.useEffect(() => {
    if (needsValidation.current) {
      needsValidation.current = false;
      const currentValidity = (Object.keys(values) as Array<keyof T>).reduce(
        (acc, key) => ({
          ...acc,
          [key]: validate(key, values[key], values),
        }),
        {},
      );

      setValid(currentValidity);
    }
  }, [values, validate]);

  const actions: FormActions<T, U> = {
    /**
     * Manually set a field validity flag (for external validation, for example)
     */
    setFieldValidity: (field: keyof T, isValid: boolean) => {
      setValid((prev) => ({
        ...prev,
        [field]: isValid,
      }));
    },
    /**
     * Field onChange handler
     */
    handleChange: (field: keyof T, value: T[keyof T]) => {
      const {valid: _valid, error: _error} = validate(field, value, values);
      setValues((prev) => ({
        ...prev,
        [field]: value,
      }));
      setDirty((prev) => ({
        ...prev,
        [field]: true,
      }));
      setValid((prev) => ({
        ...prev,
        [field]: _valid,
      }));
      setErrors((prev) => ({
        ...prev,
        [field]: _error,
      }));
    },
    /**
     * Field onBlur handler
     */
    handleBlur: (field: keyof T) => {
      const {valid: _valid, error: _error} = validate(
        field,
        values[field],
        values,
      );

      setValues((prev) => ({
        ...prev,
        [field]: transform(field, values[field]),
      }));
      setDirty((prev) => ({
        ...prev,
        [field]: true,
      }));
      setValid((prev) => ({
        ...prev,
        [field]: _valid,
      }));
      setErrors((prev) => ({
        ...prev,
        [field]: _error,
      }));
    },
    /**
     * Maps field values into output type
     */
    getOutput: () => {
      return map(values);
    },
    validateForm: () => {
      const {newValid, newDirty, newErrors} = (Object.keys(values) as Array<
        keyof T
      >).reduce((acc, field) => {
        const {valid: _valid, error: _error} = validate(
          field,
          values[field],
          values,
        );

        return merge(acc, {
          newValid: {
            [field]: _valid,
          },
          newDirty: {
            [field]: true,
          },
          newErrors:
            _error !== undefined
              ? {
                  [field]: _error,
                }
              : undefined,
        });
      }, {} as {newValid: FormFlags<T>; newDirty: FormFlags<T>; newErrors: ValidationErrors<T>});

      setValid(newValid);
      setDirty(newDirty);
      setErrors(newErrors);
      return !Object.values(newValid).some((v) => v === false);
    },

    setValues: (newValues: Partial<T>) => {
      setValues({...defaultValues, ...newValues});
      needsValidation.current = true;
    },

    setErrors: (newErrors: Partial<T>) => {
      setErrors({...errors, ...newErrors});
    },
  };

  const state = {
    values,
    valid,
    dirty,
    validationErrors: errors ?? {},
    formIsDirty,
    formIsValid,
  };

  return [state, actions] as const;
};
