import React from 'react';
import {useFela} from 'react-fela';

import {InfoIcon, CloseIcon} from '@crucible-risk/icon';
import {Typography} from '@crucible-risk/typography';
import {Button} from '@crucible-risk/button';

import {intents} from './alert.config';

import {
  alertStyle,
  contentStyle,
  messageStyle,
  actionsStyle,
  closeStyle,
  iconStyle,
  rawStyle,
} from './alert.fela';

interface Props extends Omit<React.HTMLProps<HTMLDivElement>, 'title'> {
  /**
   * Configure the color of the alert.
   */
  intent?: keyof typeof intents;

  /**
   * Display a bold alert title.
   */
  title?: React.ReactNode;

  /**
   * Display a container for raw data
   */
  raw?: React.ReactNode;

  /**
   * Accepts arbitrary react element children. Use this prop to display buttons
   * at the left of the alert which wrap responsively below when necessary.
   */
  actions?: React.ReactNode;

  /**
   * Close callback. A close button will be rendered when a value is provided
   * to this prop.
   */
  onClose?: (event: React.MouseEvent<HTMLButtonElement>) => void;
}

export const AlertRefComponent = (
  props: Props,
  ref: React.Ref<HTMLDivElement>,
) => {
  const {intent, title, raw, children, actions, onClose, ...rest} = props;

  const {css} = useFela({intent});

  return (
    <div ref={ref} {...rest} role="alert" className={css(alertStyle)}>
      <div className={css(iconStyle)}>
        <InfoIcon aria-hidden />
      </div>
      <div className={css(contentStyle)}>
        <div className={css(messageStyle)}>
          {!!title && (
            <Typography weight="semibold" fill>
              {title}
            </Typography>
          )}
          {children}
          {!!raw && <div className={css(rawStyle)}>{raw}</div>}
        </div>
        {!!actions && <div className={css(actionsStyle)}>{actions}</div>}
      </div>
      {!!onClose && (
        <div className={css(closeStyle)}>
          <Button
            aria-label="close dialog"
            intent={intent}
            minimal
            size="xSmall"
            square
            onClick={onClose}
          >
            <CloseIcon />
          </Button>
        </div>
      )}
    </div>
  );
};

export const Alert = React.forwardRef(AlertRefComponent);

export type AlertAttributes = JSX.LibraryManagedAttributes<typeof Alert, Props>;
